export function evaluate({inputs,time}){
const u=inputs.launchSpeed,g=inputs.gravity,m=inputs.mass;
const T=2*u/g,ta=u/g,t=sdk.clamp(time,0,T);
const h=u*t-g*t*t/2,v=u-g*t,ha=u*u/(2*g);
let st;
if(t<=0)st='Ready to toss';else if(Math.abs(t-ta)<0.005)st='At the top';else if(t>=T-1e-9)st='Back at launch height';else if(t<ta)st='Rising';else st='Falling';
const o=[];
o.push(...sdk.panel({id:'lane.motion',x:10,y:40,w:300,h:360,title:'The motion',state:st}));
o.push(...sdk.panel({id:'lane.graph',x:325,y:40,w:305,h:360,title:'Velocity over time',state:'v = u - g t'}));
const y0=380,sc=280/2.2;
o.push(sdk.axis('axis.h',{x:60,y:y0,length:280,orientation:'y',min:0,max:2.2,ticks:[0,1,2],label:'Height',unit:'m'}));
const by=y0-h*sc,bx=150;
o.push(sdk.circle('ball.toss',bx,by,26,{}));
o.push(...sdk.vector('vec.v',{x:bx,y:by},{value:v,direction:'up'},{scale:12,label:'v',role:'observed'}));
o.push(...sdk.vector('vec.a',{x:bx+30,y:by},{value:-g,direction:'up'},{scale:6,label:'a',role:'warning'}));
o.push(sdk.callout(200,by-30<80?80:by-30,['v '+sdk.format(v,2)+' m/s','a '+sdk.format(-g,1)+' m/s^2','Fg '+sdk.format(m*g,1)+' N'],{id:'callout.toss'}));
const N=20,pts=[];
for(let i=0;i<=N;i++){const x=1.8*i/N;pts.push({x,y:sdk.clamp(u-g*x,-5.5,5.5)});}
const cur=[];const k=12;
for(let i=0;i<=k;i++){const x=t*i/k;cur.push({x,y:sdk.clamp(u-g*x,-5.5,5.5)});}
o.push(sdk.plot('plot.vt',{x:355,y:70,w:270,h:300,axes:{x:{label:'t',min:0,max:1.8,unit:'s'},y:{label:'v',min:-5.5,max:5.5,unit:'m/s'}},series:[{label:'v=u-gt',kind:'line',points:pts},{label:'so far',kind:'line',points:cur}]}));
return{frame:{width:640,height:420,objects:o,readouts:[{id:'velocity',value:v},{id:'acceleration',value:-g},{id:'force',value:m*g},{id:'motionState',value:st}]},quantities:{launchSpeed:u,gravity:g,mass:m,apexTime:ta,apexHeight:ha,height:h,velocity:v,acceleration:-g,force:m*g}};}
